            {
                edge.disposition = PairDisposition::Rejected;
                edge.reason = PairReason::PersonOrganisationConflict;
                continue;
            }
            if a.address_match_quality == AddressMatchQuality::NumberedStreet
                && b.address_match_quality == AddressMatchQuality::NumberedStreet
                && a.address_normalized.is_some()
                && b.address_normalized.is_some()
                && a.address_normalized != b.address_normalized
            {
                edge.disposition = PairDisposition::Rejected;
                edge.reason = PairReason::FullAddressDisagreement;
                continue;
            }
            if !strong(input, edge) {
                continue;
            }
            if ambiguous.contains(&edge.left_funder_id) || ambiguous.contains(&edge.right_funder_id)
            {
                edge.reason = PairReason::CompetingCompanyAnchors;
                continue;
            }
            let left = self.group[&edge.left_funder_id];
            let right = self.group[&edge.right_funder_id];
            let ids = self.members[left]
                .union(&self.members[right])
                .cloned()
                .collect::<BTreeSet<_>>();
            let companies = ids
                .iter()
                .filter_map(|id| company(&input.observations[id]))
                .collect::<BTreeSet<_>>();
            let kinds = ids
                .iter()
                .map(|id| kind(&input.observations[id]))
                .collect::<Vec<_>>();
            if companies.len() > 1
                || (kinds.contains(&EntityKind::Person)
                    && kinds.contains(&EntityKind::Organisation))
            {
                edge.disposition = PairDisposition::Rejected;
                edge.reason = PairReason::ComponentIdentityConflict;
                continue;
            }
            if left != right {
                self.members[right].clear();
                self.members[left] = ids;
                for id in &self.members[left] {
                    self.group.insert(id.clone(), left);
                }
            }
            edge.disposition = PairDisposition::Accepted;
            edge.reason = PairReason::ExactNameFullAddressThreshold;
        }
    }
    fn outcomes(&self, input: &ResolutionInput, run_key: &str) -> Vec<ObservationResolution> {
        let mut observations = Vec::new();
        for observation in input.observations.values() {
            let ids = &self.members[self.group[&observation.funder_id]];
            let number = ids.iter().find_map(|id| company(&input.observations[id]));
            let (identity_id, identity_basis) = number.map_or_else(
                || {
                    if observation.name_normalized.is_none() {
                        (None, IdentityBasis::Unresolved)
                    } else {
                        let leader = ids
                            .first()
                            .expect("each observation belongs to a nonempty component")
                            .as_str();
                        (
                            Some(format!("run-local:{run_key}:{leader}")),
                            if ids.len() > 1 {
                                IdentityBasis::StatisticalLink
                            } else {
                                IdentityBasis::ProvisionalSingleton
                            },
                        )
                    }
                },
                |number| {
                    (
                        Some(format!("source-reported:companies-house:{number}")),
                        if company(observation).is_some() {
                            IdentityBasis::SourceReportedCompany
                        } else {
                            IdentityBasis::StatisticalLink
                        },
                    )
                },
            );
            observations.push(ObservationResolution {
                funder_id: observation.funder_id.clone(),
                identity_id,
                identity_basis,
            });
        }
        observations
    }
}
pub(super) fn resolve(
    input: &ResolutionInput,
    scoring: &ScoringInput,
    pairs: Vec<ScoredPair>,
    run_key: &str,
) -> Result<(Vec<ObservationResolution>, Vec<PairDecision>), EntityIngestionError> {
    let mut edges = expanded_edges(input, scoring, pairs)?;
    let mut components = Components::new(input);
    components.apply(input, &mut edges);
    Ok((
        components.outcomes(input, run_key),
        edges.into_values().collect(),
    ))
}
//! Identity decisions and payment attribution from checked cleaned evidence.

use super::{
    declaration_cleaning::{AddressMatchQuality, FunderObservationId, FunderRole, FundingEntryId},
    entity_ingestion::EntityIngestionError,
};
use serde::Serialize;
use std::collections::{BTreeMap, BTreeSet};

pub(crate) const POLICY_VERSION: &str = "funder-resolution-v1";
pub(crate) const AUTOMATIC_THRESHOLD: f64 = 0.999;

mod attribution;
mod identity;
fn invalid(message: impl Into<String>) -> EntityIngestionError {
    EntityIngestionError::DataError(message.into())
}

mod input;
use attribution::attribute;
#[cfg(test)]
use identity::company;
pub(crate) use input::{Observation, Payment, ScoredPair};
pub use input::{ResolutionInput, ScoredPairs, ScoringInput};

/// Evidence basis of an assigned identity, independent of reporting attribution.
#[derive(Clone, Copy, Debug, Serialize)]
#[serde(rename_all = "snake_case")]
pub enum IdentityBasis {
    /// An accepted captured company number, without registry verification.
    SourceReportedCompany,
    /// An accepted exact name and full address score.
    StatisticalLink,
    /// A separate local identity without evidence of a cross-observation match.
    ProvisionalSingleton,
    /// No usable name or eligible captured identifier.
    Unresolved,
}
/// One outcome for each input source-role observation.
#[derive(Serialize)]
pub struct ObservationResolution {
    pub(crate) funder_id: FunderObservationId,
    pub(crate) identity_id: Option<String>,
    pub(crate) identity_basis: IdentityBasis,
}
/// Policy disposition of one statistical candidate edge.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize)]
#[serde(rename_all = "snake_case")]
pub enum PairDisposition {
    /// The edge passed both statistical and component constraints.
    Accepted,
    /// The edge remains a candidate for human review.
    Review,
    /// Retained evidence contradicts automatic merging.
    Rejected,
}
/// Evidence reason for a candidate disposition.
#[derive(Clone, Copy, Debug, Serialize)]
#[serde(rename_all = "snake_case")]
pub enum PairReason {
    /// The initial exact name and numbered-street rule is not satisfied.
    InsufficientExactEvidence,
    /// Explicit person and organisation kinds disagree.
    PersonOrganisationConflict,
    /// Two usable numbered-street addresses disagree.
    FullAddressDisagreement,
    /// Strong candidates point to more than one company anchor.
    CompetingCompanyAnchors,
    /// A union would mix company numbers or incompatible entity kinds.
    ComponentIdentityConflict,
    /// Exact names, full addresses, threshold, and component constraints agree.
    ExactNameFullAddressThreshold,
}
/// A scored edge retained for inspection, including rejected evidence.
#[derive(Serialize)]
pub struct PairDecision {
    pub(crate) left_funder_id: FunderObservationId,
    pub(crate) right_funder_id: FunderObservationId,
    pub(crate) probability: f64,
    pub(crate) name_level: i32,
    pub(crate) address_level: i32,
    pub(crate) disposition: PairDisposition,
    pub(crate) reason: PairReason,
}
/// Source role used for one payment's reporting decision.
#[derive(Clone, Copy, Debug, Serialize)]
#[serde(rename_all = "snake_case")]
pub enum AttributionBasis {
    /// An explicitly named ultimate payer.
    ExplicitUltimatePayer,
    /// The unique root payer of the immediate linked parent.
    ParentPayer,
    /// The local donor when no ultimate-payer flag is supplied.
    Donor,
    /// The local payer when no donor or ultimate-payer flag is supplied.
    Payer,
}
/// Evidence that prevents supported reporting attribution.
#[derive(Clone, Copy, Debug, Serialize)]
#[serde(rename_all = "snake_case")]
pub enum UnavailableReason {
    /// An explicit ultimate role has no usable name.
    ExplicitUltimatePayerUnavailable,
    /// A different ultimate payer is declared but unnamed.
    DifferentUltimatePayerUnnamed,
            if let Some(id) = &observation.funding_entry_id {
                let payment = &input.payments[id];
                let role_id = match observation.role {
                    FunderRole::Donor => &payment.donor_funder_id,
                    FunderRole::Payer => &payment.payer_funder_id,
                    FunderRole::UltimatePayer => &payment.ultimate_payer_funder_id,
                };
                if role_id.as_ref() != Some(&observation.funder_id) {
                    return Err(invalid("unreferenced funding role observation"));
                }
            }
        }
        Ok(input)
    }

    /// Groups repeated feature profiles without asserting that they identify the same funder.
    #[must_use]
    pub fn scoring_input(&self, candidate_budget: usize) -> ScoringInput {
        let mut groups = BTreeMap::<(String, Option<String>), Vec<FunderObservationId>>::new();
        for observation in self.observations.values() {
            if let Some(name) = &observation.name_normalized {
                groups
                    .entry((name.clone(), observation.address_normalized.clone()))
                    .or_default()
                    .push(observation.funder_id.clone());
            }
        }
        let mut rows = Vec::new();
        let mut members = BTreeMap::new();
        for (index, ((name, address), ids)) in groups.into_iter().enumerate() {
            let key = format!("profile-{index:08}");
            rows.push(ComparisonRow {
                key: key.clone(),
                name: name.clone(),
                address: address.clone(),
                needs_resolution: ids
                    .iter()
                    .any(|id| company(&self.observations[id]).is_none()),
            });
            members.insert(key.clone(), ids.clone());
            if ids.len() > 1
                && ids
                    .iter()
                    .any(|id| company(&self.observations[id]).is_none())
            {
                let copy = format!("{key}-repeat");
                rows.push(ComparisonRow {
                    key: copy.clone(),
                    name,
                    address,
                    needs_resolution: true,
                });
                members.insert(copy, ids);
            }
        }
        ScoringInput {
            version: 1,
            candidate_budget,
            rows,
            members,
        }
    }
}

fn root_scope(pointer: &str) -> bool {
    let parts = pointer.split('/').collect::<Vec<_>>();
    parts.len() >= 4
        && parts[0].is_empty()
        && parts[1] == "versions"
        && parts[2].parse::<u32>().is_ok()
        && parts[3] == "fields"

